import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
class Fail extends Error {
  constructor(msg, code = 2) { super(msg); this.code = code }
}
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const deps = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  const dm = new Map([...cost.keys()].map((k) => [k, new Set()]))
  for (const [name, ...ds] of deps) {
    for (const x of [name, ...ds]) if (!cost.has(x)) throw new Fail(`error: unknown task ${x}`)
    for (const d of ds) dm.get(name).add(d)
  }
  const names = [...cost.keys()].sort(cmp)
  const dl = new Map(names.map((k) => [k, [...dm.get(k)].sort(cmp)]))
  return { names, cost, dl }
}

function findCycle(names, dl) {
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      const s = state.get(v)
      if (s === 1) return [...stack.slice(stack.indexOf(v)), v]
      if (!s) {
        const r = visit(v)
        if (r) return r
      }
    }
    stack.pop()
    state.set(u, 2)
    return null
  }
  for (const u of names) if (!state.get(u)) {
    const r = visit(u)
    if (r) return r
  }
  return null
}

function main(argv, input) {
  const mode = argv[0]
  let workers = 0
  if (mode === 'waves' || mode === 'explain') {
    if (argv.length !== 1) throw new Fail(USAGE)
  } else if (mode === 'pack') {
    if (argv.length !== 2) throw new Fail(USAGE)
    if (!/^[1-9][0-9]*$/.test(argv[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(argv[1])
  } else throw new Fail(USAGE)

  const { names, cost, dl } = parse(input())
  const cyc = findCycle(names, dl)
  if (cyc) throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)

  const start = new Map(), finish = new Map(), depth = new Map()
  const calc = (u) => {
    if (finish.has(u)) return
    let s = 0n, d = 0
    for (const v of dl.get(u)) {
      calc(v)
      if (finish.get(v) > s) s = finish.get(v)
      if (depth.get(v) + 1 > d) d = depth.get(v) + 1
    }
    start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
  }
  names.forEach(calc)
  let total = 0n
  for (const f of finish.values()) if (f > total) total = f
  const out = []
  if (mode === 'waves') {
    const ws = []
    for (const u of names) (ws[depth.get(u)] ??= []).push(u)
    ws.forEach((w, k) => out.push(`wave ${k}: ${w.join(' ')}`))
    out.push(`total ${total}`)
  } else if (mode === 'explain') {
    for (const u of names) out.push(`${u} start=${start.get(u)} finish=${finish.get(u)} depth=${depth.get(u)}`)
    out.push(`total ${total}`)
  } else {
    const rd = new Map(names.map((k) => [k, []]))
    for (const u of names) for (const v of dl.get(u)) rd.get(v).push(u)
    const prio = new Map()
    const pr = (u) => {
      if (prio.has(u)) return prio.get(u)
      let m = 0n
      for (const x of rd.get(u)) { const p = pr(x); if (p > m) m = p }
      prio.set(u, m + cost.get(u))
      return m + cost.get(u)
    }
    names.forEach(pr)
    const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
    const done = new Map() // started tasks -> finish
    const freeAt = new Array(Math.min(workers, names.length + 1)).fill(0n)
    const runs = freeAt.map(() => [])
    let t = 0n
    let remaining = names.length
    while (remaining > 0) {
      for (;;) {
        const wi = freeAt.findIndex((f) => f <= t)
        if (wi < 0) break
        const task = order.find((u) => !done.has(u) && dl.get(u).every((d) => done.has(d) && done.get(d) <= t))
        if (task === undefined) break
        const f = t + cost.get(task)
        done.set(task, f)
        freeAt[wi] = f
        runs[wi].push(`${task}@${t}-${f}`)
        remaining--
      }
      if (remaining === 0) break
      let next = null
      for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
      t = next
    }
    for (let i = 0; i < workers; i++) {
      const r = runs[i] ?? []
      out.push(`worker ${i}:${r.map((x) => ' ' + x).join('')}`)
    }
    out.push(`makespan ${total}`)
  }
  return out.join('\n') + '\n'
}

try {
  const res = main(process.argv.slice(2), () => readFileSync(0, 'utf8'))
  process.stdout.write(res)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
